{"source":"import json
import sys
from datetime import datetime, timezone

def solve():
    if len(sys.argv) < 2:
        return

    try:
        with open(sys.argv[1], 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return

    as_of_str = data.get('as_of')
    if not as_of_str:
        print(json.dumps([]))
        return

    try:
        as_of_dt = datetime.fromisoformat(as_of_str)
    except ValueError:
        print(json.dumps([]))
        return

    reminders = data.get('reminders', [])
    if not isinstance(reminders, list):
        print(json.dumps([]))
        return

    filtered_reminders = []

    for r in reminders:
        # Skip completed reminders
        if r.get('completed', False):
            continue

        due_val = r.get('due')
        if due_val is None:
            continue

        if not isinstance(due_val, str):
            continue

        try:
            due_dt = datetime.fromisoformat(due_val)

            # Skip if naive
            if due_dt.tzinfo is None:
                continue

            # Include if due <= as_of
            if due_dt <= as_of_dt:
                # Format due_utc as YYYY-MM-DDTHH:MM:SSZ
                due_utc_dt = due_dt.astimezone(timezone.utc)
                due_utc_str = due_utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')

                filtered_reminders.append({
                    'id': r['id'],
                    'title': r['title'],
                    'due_utc': due_utc_str,
                    'due_dt': due_dt
                })
        except (ValueError, TypeError):
            continue

    # Sort by actual due instant then id
    filtered_reminders.sort(key=lambda x: (x['due_dt'], x['id']))

    # Final output: JSON array with exactly id, title, due_utc
    output = []
    for fr in filtered_reminders:
        output.append({
            'id': fr['id'],
            'title': fr['title'],
            'due_utc': fr['due_utc']
        })

    print(json.dumps(output))

if __name__ == "__main__":
    solve()
"}

